"use server";

// Generated by philote from component SwipeDeck's calls. Do not edit.
import * as api from "@/lib/api";
import { message } from "@/lib/form";
import { needViewer } from "@/lib/viewer";

// swipe calls the swipe endpoint as the viewer. It returns the error
// to show, or undefined when it worked.
export async function swipe(input: { target: string; liked: boolean }): Promise<string | undefined> {
    const viewer = await needViewer();
    const result = await api.swipe({ horse: viewer.id, target: input.target, liked: input.liked });
    return result.ok ? undefined : message(result.error);
}
